# Builds tools/game_voice/tashkeel.json: plain sentence -> the same sentence WITH diacritics (Egyptian reading).
# Only the voice generator uses it; the games still look clips up by the plain text.
import json, re, sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
N = {'واحد':'وَاحِد','اتنين':'اتْنِينْ','تلاتة':'تَلَاتَة','أربعة':'أَرْبَعَة','خمسة':'خَمْسَة','ستة':'سِتَّة','سبعة':'سَبْعَة','تمانية':'تَمَانْيَة','تسعة':'تِسْعَة','عشرة':'عَشَرَة',
 'حداشر':'حْدَاشَر','اتناشر':'اتْنَاشَر','تلاتاشر':'تَلَاتَاشَر','أربعتاشر':'أَرْبَعْتَاشَر','خمستاشر':'خَمَسْتَاشَر','ستاشر':'سِتَّاشَر','سبعتاشر':'سَبَعْتَاشَر','تمنتاشر':'تَمَنْتَاشَر','تسعتاشر':'تِسَعْتَاشَر','عشرين':'عِشْرِين','تلاتين':'تَلَاتِين'}
M = dict(N)
for k in ['واحد','اتنين','تلاتة','أربعة','خمسة','ستة','سبعة','تمانية','تسعة']:
    M[k + ' وعشرين'] = N[k] + ' وَعِشْرِين'
cnt = ['واحد','اتنين','تلاتة','أربعة','خمسة','ستة']
for i in range(2, 7):
    M['، '.join(cnt[:i])] = '، '.join(N[x] for x in cnt[:i])
words = {'أتوبيس':'أُتُوبِيس','أرنب':'أَرْنَب','برتقانة':'بُرْتُقَانَة','بطيخ':'بِطِّيخ','تفاحة':'تُفَّاحَة','دبدوب':'دُبْدُوب','سمكة':'سَمَكَة','ضفدع':'ضِفْدَع','طبلة':'طَبْلَة','طيارة':'طَيَّارَة','عربية':'عَرَبِيَّة','عنب':'عِنَب','فراولة':'فَرَاوْلَة','قطة':'قِطَّة','قطر':'قَطْر','كتكوت':'كَتْكُوت','كمثرى':'كُمَّثْرَى','كورة':'كُورَة','مركب':'مَرْكَب','مكعبات':'مُكَعَّبَات','موزة':'مَوْزَة','يويو':'يُويُو'}
defin = {'الأتوبيس':'الأُتُوبِيس','الأرنب':'الأَرْنَب','البرتقانة':'البُرْتُقَانَة','البطيخ':'البِطِّيخ','التفاحة':'التُّفَّاحَة','الدبدوب':'الدُّبْدُوب','السمكة':'السَّمَكَة','الضفدع':'الضِّفْدَع','الطبلة':'الطَّبْلَة','الطيارة':'الطَّيَّارَة','العربية':'العَرَبِيَّة','العنب':'العِنَب','الفراولة':'الفَرَاوْلَة','القطة':'القِطَّة','القطر':'القَطْر','الكتكوت':'الكَتْكُوت','الكمثرى':'الكُمَّثْرَى','الكورة':'الكُورَة','المركب':'المَرْكَب','المكعبات':'المُكَعَّبَات','الموزة':'المَوْزَة','اليويو':'اليُويُو'}
M.update(words)
cat = {'عربيات':'عَرَبِيَّات','حيوانات':'حَيَوَانَات','فاكهة':'فَاكْهَة','لعب':'لُعَب'}
for d, dv in defin.items():
    for c, cv in cat.items():
        M[d + ' ' + c + '!'] = dv + ' ' + cv + '!'
pl = {'البركة':'البِرْكَة','الصخرة':'الصَّخْرَة','العلم':'العَلَم','الكوخ':'الكُوخ','النخلة':'النَّخْلَة'}
pre = {'تحت':'تَحْت','جنب':'جَنْب','شمال':'شِمَال','فوق':'فُوق','يمين':'يِمِين','في نفس صف':'فِي نَفْس صَفّ','في نفس عمود':'فِي نَفْس عَمُود'}
for p, pv in pl.items():
    for a, av in pre.items():
        M['الكنز ' + a + ' ' + p] = 'الكَنْز ' + av + ' ' + pv
for a, av in {'تحت':'تَحْت','جنب':'جَنْب','فوق':'فُوق'}.items():
    M['الكورة ' + a + ' الترابيزة'] = 'الكُورَة ' + av + ' التَّرَابِيزَة'
M['الكورة جنب الصندوق'] = 'الكُورَة جَنْب الصُّنْدُوق'
M['الكورة جوه الصندوق'] = 'الكُورَة جُوَّه الصُّنْدُوق'
M.update({
'آخد دُش':'آخُد دُشّ','أتعشّى':'أَتْعَشَّى','أتغدّى':'أَتْغَدَّى','أروح الحضانة':'أَرُوح الحَضَانَة','أصحى من النوم':'أَصْحَى مِن النَّوْم','أغسل سناني':'أَغْسِل سِنَانِي','أغسل وشّي':'أَغْسِل وِشِّي','أفطر':'أَفْطَر','ألعب':'أَلْعَب','أنام':'أَنَام',
'إيه أول حاجة؟':'إِيه أَوِّل حَاجَة؟','إيه الخرزة اللي جاية؟':'إِيه الخَرَزَة اللِّي جَايَة؟','اسحب الحاجة للسلة، أو دوس على السلة':'اسْحَب الحَاجَة لِلسَّلَّة، أَو دُوس عَلَى السَّلَّة',
'اسمع الببغاء وادور على الكنز!':'اسْمَع البَبَّغَاء وَادَوَّر عَلَى الكَنْز!','اسمع تاني':'اسْمَع تَانِي','الرف خلص! برافو':'الرَّفّ خِلِص! بَرَافُو','السلالم والزلاجات':'السَّلَالِم وَالزَّلَّاجَات',
'الدبدوب وصل الأول! برافو عليكم':'الدُّبْدُوب وِصِل الأَوَّل! بَرَافُو عَلَيْكُم','برافو! كمّلت النمط':'بَرَافُو! كَمَّلْت النَّمَط','برافو! كمّلتي النمط':'بَرَافُو! كَمَّلْتِي النَّمَط',
'برافو! لقيت الكورة':'بَرَافُو! لْقِيت الكُورَة','برافو! لقيتي الكورة':'بَرَافُو! لْقِيتِي الكُورَة','بوبي خبّى الكورة! اسمع وقول هي فين':'بُوبِي خَبَّى الكُورَة! اسْمَع وَقُول هِي فِين',
'حط كل حاجة في السلة بتاعتها!':'حُطّ كُلّ حَاجَة فِي السَّلَّة بِتَاعْتَهَا!','حلقة بنفسجي':'حَلَقَة بَنَفْسَجِي','خلصتها تاني! برافو عليك':'خَلَّصْتَهَا تَانِي! بَرَافُو عَلَيْك','خلصتها تاني! برافو عليكي':'خَلَّصْتَهَا تَانِي! بَرَافُو عَلَيْكِي',
'ده مكان مش للحفر':'دَه مَكَان مِش لِلْحَفْر','دور الدبدوب':'دَوْر الدُّبْدُوب','دورك! دوس على الزهر':'دَوْرَك! دُوس عَلَى الزَّهْر','دورك! دوسي على الزهر':'دَوْرِك! دُوسِي عَلَى الزَّهْر',
'دوس على المكان اللي فيه الكنز':'دُوس عَلَى المَكَان اللِّي فِيه الكَنْز','رتّب في مجموعات':'رَتَّب فِي مَجْمُوعَات','رتّب يومك! إيه اللي بيحصل الأول؟':'رَتِّب يَوْمَك! إِيه اللِّي بِيْحْصَل الأَوَّل؟','رتّب يومي':'رَتِّب يَوْمِي',
'زحليقة! وييي':'زَحْلِيقَة! وِييِي','سلّم! اطلع لفوق':'سُلَّم! اطْلَع لِفُوق','شاطر أوي! خدت نجمة جديدة!':'شَاطِر أَوِي! خَدْت نَجْمَة جْدِيدَة!','شاطره أوي! خدتي نجمة جديدة!':'شَاطْرَه أَوِي! خَدْتِي نَجْمَة جْدِيدَة!',
'فين الكورة؟':'فِين الكُورَة؟','قلب أخضر':'قَلْب أَخْضَر','كمّل النمط':'كَمِّل النَّمَط','كنز الجزيرة':'كَنْز الجَزِيرَة','كورة حمرا':'كُورَة حَمْرَا','لسه بدري عليها!':'لِسَّه بَدْرِي عَلَيْهَا!',
'لقيت الكنز! شاطر':'لْقِيت الكَنْز! شَاطِر','لقيتي الكنز! شاطره':'لْقِيتِي الكَنْز! شَاطْرَه','مش دي... بُص على الترتيب تاني':'مِش دِي... بُصّ عَلَى التَّرْتِيب تَانِي','مش دي... جرّب سلة تانية':'مِش دِي... جَرَّب سَلَّة تَانْيَة',
'مش هنا... اسمع الببغاء تاني':'مِش هِنَا... اسْمَع البَبَّغَاء تَانِي','مش هنا... اسمع تاني':'مِش هِنَا... اسْمَع تَانِي','مكعب أزرق':'مُكَعَّب أَزْرَق','نجمة صفرا':'نَجْمَة صَفْرَا','نقطة برتقالي':'نُقْطَة بُرْتُقَالِي',
'وبعدين؟':'وَبَعْدِين؟','وصلت للعلم الأول!':'وِصِلْت لِلْعَلَم الأَوَّل!','وصلتي للعلم الأول!':'وِصِلْتِي لِلْعَلَم الأَوَّل!','يوم جميل! رتّبته صح':'يَوْم جَمِيل! رَتَّبْتُه صَحّ','يوم جميل! رتّبتيه صح':'يَوْم جَمِيل! رَتَّبْتِيه صَحّ'})
# second round after listening (owner): clearer forms, final sukun, imperative vowels
M.update({
'اتناشر':'اِتْنَاشَرْ','حداشر':'أَحَدَ عَشَرَ','تلاتاشر':'تَلَاتَاشَرْ','ستاشر':'سِتَّاشَرْ',
'كتكوت':'كَتْكُوت','نجمة صفرا':'نَجْمَةْ صَفْرَا','الدبدوب لعب!':'الدُّبْدُوب لُعَبْ!',
'بوبي خبّى الكورة! اسمع وقول هي فين':'بُوبِي خَبَّى الكُورَة! اسْمَع وَقُول هِيَّ فِينْ',
'خلصتها تاني! برافو عليك':'خَلَّصْتْهَا تَانِي! بَرَافُو عَلَيكْ','خلصتها تاني! برافو عليكي':'خَلَّصْتِيهَا تَانِي! بَرَافُو عَلَيكِي',
'رتّب في مجموعات':'رَتِّب فِي مَجْمُوعَاتْ','يوم جميل! رتّبتيه صح':'يَوْم جَمِيل! رَتَّبْتِيهْ صَحّ'})
import tashkeel_games
tashkeel_games.add(M)
import tashkeel_levels
tashkeel_levels.add(M)
strip = lambda s: re.sub('[ً-ْـٰ]', '', s)
lines = [l['text'] for l in json.load(open('assets/games/learn_voice/lines.json', encoding='utf8')) if l['lang'] == 'ar']
miss = [t for t in lines if t not in M]
# the voice may read a slightly different spelling than the on-screen text (owner choice); only these may differ
SPELLING = {'خلصتها تاني! برافو عليكي', 'حداشر', 'فين رقم حداشر؟', 'شاطره أوي!', 'شاطره أوي! خدتي نجمة جديدة!', 'لقيتي الكنز! شاطره'}
bad = [(k, v) for k, v in M.items() if strip(k) != strip(v) and k not in SPELLING]
print('lines', len(lines), 'missing', miss, 'mismatch', bad)
if miss or bad:
    sys.exit(1)
json.dump({t: M[t] for t in lines}, open('tools/game_voice/tashkeel.json', 'w', encoding='utf8'), ensure_ascii=False, indent=0)
print('written', len(lines), 'chars', sum(len(M[t]) for t in lines))
